/* Search and grid paging for the asset catalog (one page, generated by
  tools/scripts/brand/generate-internal-asset-catalog.py in blowhorn). The
  kind, status, segment, profile and funnel filters are CSS radio buttons
  and need no script; this file adds what CSS cannot do: a search field that
  matches a row or card's text, and paging for the grid view. Without it the
  page still works: the table, the filters and the grid all render, the grid
  just shows every card unpaged, and a thumbnail link still opens the
  full-size file. The search reads ?q= on load, so the section page's search
  box lands here with its query filled in. Pure helpers are exported for
  node:test. */
export const PAGE_SIZE = 48;

export function matchesQuery(text, q) {
  return !q || text.toLowerCase().indexOf(q.toLowerCase()) !== -1;
}

export function cardMatches(card, filters) {
  if (filters.kind === 'clips') return false;
  if (filters.kind !== 'all' && card.kind !== filters.kind) return false;
  if (filters.status !== 'all' && card.status !== filters.status) return false;
  return matchesQuery(card.text, filters.q);
}

export function pageOf(items, page) {
  var pages = Math.max(1, Math.ceil(items.length / PAGE_SIZE));
  var p = Math.min(Math.max(1, page), pages);
  return { items: items.slice((p - 1) * PAGE_SIZE, p * PAGE_SIZE), page: p, pages: pages };
}

export function searchCountText(files, totalFiles, clips, totalClips, q) {
  return q
    ? files + ' of ' + totalFiles + ' files, ' + clips + ' of ' + totalClips + ' clips match "' + q + '"'
    : '';
}

function kindOf(className) {
  var match = className.match(/\bk-([a-z-]+)/);
  return match ? match[1] : 'all';
}

function statusOf(className) {
  var match = className.match(/\bst-([a-z-]+)/);
  return match ? match[1] : 'all';
}

export function boot(doc) {
  var search = doc.getElementById('ac-search');
  var count = doc.getElementById('ac-search-count');
  var grid = doc.getElementById('ac-grid');
  if (!search || !grid) return;

  var fileRows = Array.prototype.slice.call(doc.querySelectorAll('.ac-files tbody tr.r'));
  var clipRows = Array.prototype.slice.call(doc.querySelectorAll('.ac-clips tbody tr.r'));
  var cards = Array.prototype.slice.call(grid.querySelectorAll('.ac-card')).map(function (el) {
    return { el: el, kind: kindOf(el.className), status: statusOf(el.className), text: el.textContent };
  });
  var prev = doc.getElementById('ac-prev');
  var next = doc.getElementById('ac-next');
  var label = doc.getElementById('ac-page-label');
  var page = 1;

  function query() {
    return search.value.trim().toLowerCase();
  }

  function selected(group) {
    var checked = doc.querySelector('input[name="ac-' + group + '"]:checked');
    return checked ? checked.id.replace('ac-' + group + '-', '') : 'all';
  }

  // The cards the grid shows: matching the search and the kind and status
  // radios. The clips choice hides the whole files section in CSS, so the
  // grid is empty then.
  function visibleCards() {
    var filters = { kind: selected('kind'), status: selected('status'), q: query() };
    return cards.filter(function (card) {
      return cardMatches(card, filters);
    });
  }

  function showPage() {
    var visible = visibleCards();
    var paged = pageOf(visible, page);
    page = paged.page;
    cards.forEach(function (card) {
      card.el.style.display = 'none';
    });
    paged.items.forEach(function (card) {
      card.el.style.display = '';
    });
    if (label) {
      label.textContent = visible.length === 0
        ? 'No files match'
        : 'Page ' + paged.page + ' of ' + paged.pages + ' (' + visible.length + ' files)';
    }
    if (prev) prev.disabled = page <= 1;
    if (next) next.disabled = page >= paged.pages;
  }

  function applySearch() {
    var q = query();
    var files = 0;
    var clips = 0;
    fileRows.forEach(function (row) {
      var show = matchesQuery(row.textContent, q);
      row.style.display = show ? '' : 'none';
      if (show) files++;
    });
    clipRows.forEach(function (row) {
      var show = matchesQuery(row.textContent, q);
      row.style.display = show ? '' : 'none';
      if (show) clips++;
    });
    if (count) {
      count.textContent = searchCountText(files, fileRows.length, clips, clipRows.length, search.value.trim());
    }
    page = 1;
    showPage();
  }

  search.addEventListener('input', applySearch);

  var catalog = doc.querySelector('.ac');
  if (catalog) {
    catalog.addEventListener('change', function () {
      page = 1;
      showPage();
    });
  }
  if (prev) prev.addEventListener('click', function () {
    if (page > 1) {
      page--;
      showPage();
    }
  });
  if (next) next.addEventListener('click', function () {
    page++;
    showPage();
  });

  if (typeof window !== 'undefined') {
    var params = new URLSearchParams(window.location.search);
    if (params.has('q')) search.value = params.get('q');
  }
  applySearch();
}

export const AssetCatalog = {
  PAGE_SIZE,
  matchesQuery,
  cardMatches,
  pageOf,
  searchCountText,
  boot,
};

if (typeof globalThis !== 'undefined') globalThis.AssetCatalog = AssetCatalog;

if (typeof document !== 'undefined' && document.querySelector) {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { boot(document); }, { once: true });
  else boot(document);
}
